mapper.select:
SELECT @rownum:=@rownum+1 as num  ,a.*
from (SELECT @rownum:=0) r,(
select t.* from (







			UNION ALL





) t order by mdateUnadjust desc,IFNULL(adjustNum,0) desc
) a

select A.FINPROD_ID id, CONCAT_WS('',A.FINPROD_MARKET_ID ,':', A.FINPROD_ABBR) text
from FIN_PRODUCT A
inner join FIN_PRODUCT_ADD B
on A.FINPROD_ID = B.FINPROD_ID
and B.ISSUE_STATUS = #{ISSUE_STATUS01}
left join PTL_PORTFOLIO_AUTHORITY C

on B.PORTFOLIO_ID = C.PORTFOLIO_ID
where A.P_FINPROD_ID IS NULL

	and A.MDATE >= STR_TO_DATE(#{platDate},'%Y-%m-%d')

and A.FINPROD_TYPE2 = #{finprodType2}

	and (instr(A.FINPROD_MARKET_ID, #{search}) > 0 or instr(A.FINPROD_ABBR, #{search}) > 0)



		and A.FINPROD_ID = #{initValue}


		and C.USER_ID = #{userId}

select
IFNULL(T.MDATE, FP.MDATE) mdate , IFNULL(T.LDATE, FP.LIQUIDATION_DATE) ldateUnadjust , FP.FINPROD_ABBR finprodAbbr, FP.FINPROD_MARKET_ID finprodMarketId, IFNULL(T.adjustNum, 0) adjustNum, FP.VDATE vdate, FP.CALENDAR_ID calendarId, FPA.DEAL_MODE dealMode, FP.PROFIT_TYPE profitType from FIN_PRODUCT FP
left join FIN_PRODUCT_ADD FPA ON FP.FINPROD_ID = FPA.FINPROD_ID left join (select FINPROD_ID, MDATE,LDATE,ADJUST_NUM adjustNum from PRD_MDATE_ADJUST where FINPROD_ID = #{finprodId} and ADJUST_NUM = ( SELECT MAX(T.ADJUST_NUM) FROM PRD_MDATE_ADJUST T WHERE T.FINPROD_ID = #{finprodId}) ) T on FP.FINPROD_ID = T.FINPROD_ID where FP.FINPROD_ID = #{finprodId}

select count(1) from TRD_FIN_PRODUCT_DEAL_TOTAL TFPD, FIN_PRODUCT FP
where TFPD.FINPROD_ID = FP.FINPROD_ID
and TFPD.FINPROD_TYPE2 = #{finprodType2}
and FP.FINPROD_TYPE2 = #{finprodType2}
and FP.FINPROD_ID = #{finprodId}
and TFPD.TRADE_DATE >= STR_TO_DATE(#{mdate}, '%Y-%m-%d')
and TFPD.TRADE_STATUS = #{tradeStatus}

select IFNULL(max(adjust_num),0) adjustNum
from PRD_MDATE_ADJUST
where FINPROD_ID=#{finprodId}

mapper.sql:
select FP.FINPROD_MARKET_ID finprodMarketId, FP.FINPROD_ABBR finprodAbbr, NULL AS adjusttype, FP.MDATE mdateUnadjust, FP.LIQUIDATION_DATE ldateUnadjust, NULL AS ldate, NULL AS bdate, NULL AS rdate, NULL AS mdate, NULL AS remark, FP.FINPROD_ID finprodId, NULL AS adjustNum, NULL AS status, PMSI.SEND_STATUS sendStatus, PMSI.SEND_REMARK sendRemark from FIN_PRODUCT_ADD FPA, PTL_PORTFOLIO_AUTHORITY PPA, FIN_PRODUCT FP LEFT JOIN INF_PRD_MDATE_ADJUST PMSI ON FP.FINPROD_ID = PMSI.FINPROD_ID where FP.FINPROD_ID = FPA.FINPROD_ID and FPA.PORTFOLIO_ID = PPA.PORTFOLIO_ID and PPA.USER_ID = #{userId} and FP.FINPROD_TYPE2 = #{finprodType2} and FP.P_FINPROD_ID IS NULL and date_format(FP.MDATE, '%Y-%m-%d %H%-%i-%s') >= #{platDate} and FPA.ISSUE_STATUS = #{ISSUE_STATUS01}
and FP.FINPROD_ID IN
#{item}
AND IFNULL(PMSI.SEND_STATUS, '03') = #{sendStatus,jdbcType=VARCHAR}
and not exists (select 1 from PRD_MDATE_ADJUST where FP.FINPROD_ID = PRD_MDATE_ADJUST.FINPROD_ID)

select FP.FINPROD_MARKET_ID finprodMarketId, FP.FINPROD_ABBR finprodAbbr, PMAD.ADJUST_TYPE adjusttype, PMAD.MDATE_UNADJUST mdateUnadjust, PMAD.LDATE_UNADJUST ldateUnadjust,
PMAD.LDATE ldate, (CASE WHEN PMAD.ADJUST_TYPE = #{TZLX_TQZZ} THEN PMAD.MDATE ELSE NULL END) bdate,
(CASE WHEN PMAD.ADJUST_TYPE = #{TZLX_CPZQ} THEN PMAD.MDATE ELSE NULL END) rdate,
(CASE WHEN PMAD.ADJUST_TYPE = #{TZLX_DQRTZ} THEN PMAD.MDATE ELSE NULL END) mdate,
PMAD.REMARK remark, FP.FINPROD_ID finprodId, PMAD.ADJUST_NUM adjustNum, (CASE WHEN PMAD.ADJUST_NUM = (select max(ADJUST_NUM) from PRD_MDATE_ADJUST pma where pma.FINPROD_ID=PMAD.FINPROD_ID) THEN 'E' ELSE 'D' END) status,
PMSI.SEND_STATUS sendStatus, PMSI.SEND_REMARK sendRemark from PRD_MDATE_ADJUST PMAD, FIN_PRODUCT_ADD FPA, PTL_PORTFOLIO_AUTHORITY PPA, FIN_PRODUCT FP LEFT JOIN INF_PRD_MDATE_ADJUST PMSI ON FP.FINPROD_ID = PMSI.FINPROD_ID where FP.FINPROD_ID = PMAD.FINPROD_ID and FP.FINPROD_ID = FPA.FINPROD_ID
and FPA.PORTFOLIO_ID = PPA.PORTFOLIO_ID and PPA.USER_ID = #{userId} and FP.FINPROD_TYPE2 = #{finprodType2} and FPA.ISSUE_STATUS = #{ISSUE_STATUS01}
and FP.FINPROD_ID IN
#{item}
and PMAD.MDATE >= STR_TO_DATE(#{adjustAfterMdateStart}, '%Y-%m-%d')
and PMAD.MDATE <= STR_TO_DATE(#{adjustAfterMdateEnd}, '%Y-%m-%d')
and PMAD.ADJUST_TYPE = #{adjustType}
AND IFNULL(PMSI.SEND_STATUS, '03') = #{sendStatus,jdbcType=VARCHAR}
